package api

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
	"time"
)

const cursorVersion = "v1"

type cursorPayload struct {
	Version       string `json:"v"`
	CreatedNano   int64  `json:"created_nano"`
	CreatedID     string `json:"record_id"`
}

func encodeCursor(position storeCursor) (string, error) {
	payload, err := json.Marshal(cursorPayload{
		Version:     cursorVersion,
		CreatedNano: position.CreatedAt.UnixNano(),
		CreatedID:   position.RecordID,
	})
	if err != nil {
		return "", err
	}
	return cursorVersion + "." + base64.RawURLEncoding.EncodeToString(payload), nil
}

func decodeCursor(encoded string) (storeCursor, error) {
	version, data, ok := strings.Cut(encoded, ".")
	if !ok || version != cursorVersion {
		return storeCursor{}, errors.New("cursor version mismatch")
	}
	raw, err := base64.RawURLEncoding.DecodeString(data)
	if err != nil {
		return storeCursor{}, err
	}
	var payload cursorPayload
	if err := json.Unmarshal(raw, &payload); err != nil {
		return storeCursor{}, err
	}
	if payload.Version != cursorVersion || payload.CreatedID == "" || payload.CreatedNano <= 0 {
		return storeCursor{}, errors.New("cursor payload invalid")
	}
	return storeCursor{CreatedAt: time.Unix(0, payload.CreatedNano).UTC(), RecordID: payload.CreatedID}, nil
}
